/* Candyland Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="candyland-light"] {
  --background: rgb(248, 248, 248);
  --foreground: rgb(51, 51, 51);
  --card: rgb(255, 255, 255);
  --card-foreground: rgb(51, 51, 51);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(51, 51, 51);
  --primary: rgb(254, 194, 204);
  --primary-foreground: rgb(0, 0, 0);
  --secondary: rgb(135, 204, 232);
  --secondary-foreground: rgb(0, 0, 0);
  --muted: rgb(220, 216, 194);
  --muted-foreground: rgb(111, 111, 111);
  --accent: rgb(254, 255, 85);
  --accent-foreground: rgb(0, 0, 0);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(212, 212, 212);
  --input: rgb(212, 212, 212);
  --ring: rgb(254, 194, 204);
  --chart-1: rgb(254, 194, 204);
  --chart-2: rgb(135, 204, 232);
  --chart-3: rgb(254, 255, 85);
  --chart-4: rgb(255, 151, 203);
  --chart-5: rgb(47, 205, 48);
  --radius: 0.5rem;
  --sidebar: rgb(248, 248, 248);
  --sidebar-foreground: rgb(51, 51, 51);
  --sidebar-primary: rgb(254, 194, 204);
  --sidebar-primary-foreground: rgb(0, 0, 0);
  --sidebar-accent: rgb(254, 255, 85);
  --sidebar-accent-foreground: rgb(0, 0, 0);
  --sidebar-border: rgb(212, 212, 212);
  --sidebar-ring: rgb(254, 194, 204);
  --font-sans: Poppins, sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: Roboto Mono, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

