  --popover-foreground: rgb(228, 228, 228);
  --primary: rgb(255, 151, 203);
  --primary-foreground: rgb(0, 0, 0);
  --secondary: rgb(47, 205, 48);
  --secondary-foreground: rgb(0, 0, 0);
  --muted: rgb(69, 69, 69);
  --muted-foreground: rgb(164, 164, 164);
  --accent: rgb(135, 204, 232);
  --accent-foreground: rgb(0, 0, 0);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(69, 69, 69);
  --input: rgb(69, 69, 69);
  --ring: rgb(255, 151, 203);
  --chart-1: rgb(255, 151, 203);
  --chart-2: rgb(47, 205, 48);
  --chart-3: rgb(135, 204, 232);
  --chart-4: rgb(254, 255, 85);
  --chart-5: rgb(255, 206, 39);
  --radius: 0.5rem;
  --sidebar: rgb(27, 29, 34);
  --sidebar-foreground: rgb(228, 228, 228);
